interface.definition:
a!localVariables(

  local!reviewersComment: index(
    ri!nomination,
    "vettingReviewersComment",
    {}
  ),
  local!createdOn: index(ri!nomination, "createdOn", {}),
  local!isNewVersion: if(
    a!isNullOrEmpty(local!createdOn),
    true,
    if(
      todatetime(local!createdOn) > #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false
    )
  ),
    local!userBU: a!refreshVariable(
      value: union(
        reject(
          fn!isnull,
          #"SYSTEM_SYSRULES_forEach"(
            items: getgroupsformemberuser(user: loggedInUser()),
            expression: {
              a!localVariables(
                local!groupName: group(fv!item, "groupName"),
                local!list: split(local!groupName, " "),
                local!length: length(local!list),
                if(
                  and(
                    local!length > 2,
                    contains(local!list, "CAW"),
                    or(
                      contains(local!list, "BUPPP"),
                      contains(local!list, "BUPIC"),
                      contains(local!list, "BUPPP_BUPIC"),
                      contains(local!list, "BUCos"),
                      contains(local!list, "CoS/Delegate")
                    )
                  ),
                  joinarray(
                    remove(local!list, { 1, local!length }),
                    " "
                  ),
                  null
                )
              )
            }
          )
        ),
        reject(
          fn!isnull,
          #"SYSTEM_SYSRULES_forEach"(
            items: getgroupsformemberuser(user: loggedInUser()),
            expression: {
              a!localVariables(
                local!groupName: group(fv!item, "groupName"),
                local!list: split(local!groupName, " "),
                local!length: length(local!list),
                if(
                  and(
                    local!length > 2,
                    contains(local!list, "CAW"),
                    or(
                      contains(local!list, "BUPPP"),
                      contains(local!list, "BUPIC"),
                      contains(local!list, "BUPPP_BUPIC"),
                      contains(local!list, "BUCos"),
                      contains(local!list, "CoS/Delegate")
                    )
                  ),
                  joinarray(
                    remove(local!list, { 1, local!length }),
                    " "
                  ),
                  null
                )
              )
            }
          )
        )
      ),
      refreshAlways: true
    ),
    local!ismemberofusergroup:or(
      contains(
        touniformstring(local!userBU),
        tostring(ri!nomination.originatingBU)
      ),
      contains(
        touniformstring(local!userBU),
        tostring(ri!nomination.returnBU)
      ),
      a!isNullOrEmpty(local!userBU)),
      if(
        local!ismemberofusergroup,
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_sectionLayout_v1"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    labelPosition: "COLLAPSED",
                    value: {
                      #"SYSTEM_SYSRULES_richTextHeader"(text: "", size: "MEDIUM")
                    }
                  )
                }
              ),
              #"SYSTEM_SYSRULES_forEach"(
                items: ri!comments,
                expression: #"SYSTEM_SYSRULES_sectionLayout_v1"(
                  contents: {
                    #"SYSTEM_SYSRULES_sideBySideLayout"(
                      items: {
                        #"SYSTEM_SYSRULES_sideBySideItem"(
                          item: #"SYSTEM_SYSRULES_stampField"(
                            labelPosition: "COLLAPSED",
                            text: if(
                              validateemailaddress(fv!item.createdBy) = true,
                              initials(
                                #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(fv!item.createdBy)
                              ),
                              initials(fv!item.createdBy)
                            ),
                            backgroundColor: "SECONDARY",
                            size: "SMALL"
                          ),
                          width: "MINIMIZE"
                        ),
                        #"SYSTEM_SYSRULES_sideBySideItem"(
                          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: {
                              #"SYSTEM_SYSRULES_richTextItem_v1"(
                                color: "ACCENT",
                                text: if(
                                  validateemailaddress(fv!item.createdBy) = true,
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(fv!item.createdBy),
                                  fv!item.createdBy
                                ),
                                style: "STRONG"
                              ),
                              char(10),
                              #"SYSTEM_SYSRULES_richTextItem_v1"(
                                text: fv!item.createdOn,
                                color: "SECONDARY"
                              )
                            }
                          )
                        )
                      },
                      alignVertical: "MIDDLE"
                    ),
                    #"SYSTEM_SYSRULES_textField"(
                      labelPosition: "COLLAPSED",
                      value: fv!item.comment,
                      readOnly: true
                    )
                  }
                )
              )
            },
            width: "WIDE"
          ),
          #"SYSTEM_SYSRULES_columnLayout"()
        }
      ),
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        labelPosition: "COLLAPSED",
        value: {
          #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: "No Comments Found",
            style: "STRONG"
          )
        },
        showWhen: and(#"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!comments), a!isNullOrEmpty(ri!nomination.vettingReviewersComment), a!isNullOrEmpty(local!reviewersComment)),
        align: "CENTER"
      ),
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        value: {
          #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: "Additional Vetting reviewer's Comments",
            style: "STRONG",
            size: "MEDIUM",
            showWhen:  if(
              and(
                toboolean(local!isNewVersion) = true,
                a!isNotNullOrEmpty(local!reviewersComment),
                #"urn:appian:function:v1:a:isusermemberofgroup?okey=a!isUserMemberOfGroup"(
                  username: loggedInUser(),
                  groups: 

                  {
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922",
                    #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12648325",
                    #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12645233",
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177083",
                    #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066240",
                    #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066222",
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177089",

                  }

                ),

              ),
              true,
              false
            ),
          ),
          char(10),
          #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: local!reviewersComment,
            showWhen: if(
              and(
                toboolean(local!isNewVersion) = true,
                #"urn:appian:function:v1:a:isusermemberofgroup?okey=a!isUserMemberOfGroup"(
                  username: loggedInUser(),
                  groups: 

                  {
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922",
                    #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12648325",
                    #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12645233",
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177083",
                    #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066240",
                    #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066222",
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177089"
                  }

                ),

              ),
              true,
              false
            ),
          )

        }
      ),

    },
    showWhen: ri!showWhen
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    contents: #"SYSTEM_SYSRULES_cardLayout"(
      contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
        value: #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: "You are not able to view this nomination because you are not a part of the  " & touniformstring(ri!nomination.originatingBU) &" Group", 
          style: "STRONG",
          size: "MEDIUM",

        )
      )
    )
  ),

      )
)
